import{_ as t,o as a,c as e,a5 as s}from"./chunks/framework.QWVCgkrI.js";const o="/study/images/graphics/transforms-and-cameras.svg",f=JSON.parse('{"title":"座標変換とカメラの基本 — モデルの位置が画面に映るまで","description":"","frontmatter":{"title":"座標変換とカメラの基本 — モデルの位置が画面に映るまで","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"graphics","summary":"物体を移動・回転・拡縮する操作から、ローカル、ワールド、ビュー、投影、画面座標の意味を説明する。透視投影と正投影、座標規約の違いも比べる。","aliases":["座標変換","transform","ローカル座標","モデル座標","ワールド座標","ビュー座標","カメラ座標","投影","透視投影","正投影","FOV","視野角","クリッピング"],"verification":"Microsoftの座標変換、UnityのTransformとCamera、KhronosのglTFの座標・カメラ仕様に照合（2026-11-07）"}},"headers":[],"relativePath":"graphics/basics/transforms-and-cameras.md","filePath":"graphics/basics/transforms-and-cameras.md"}'),n={name:"graphics/basics/transforms-and-cameras.md"};function i(d,r,c,h,l,m){return a(),e("div",null,[...r[0]||(r[0]=[s('<h1 id="座標変換とカメラの基本-—-モデルの位置が画面に映るまで" tabindex="-1">座標変換とカメラの基本 — モデルの位置が画面に映るまで <a class="header-anchor" href="#座標変換とカメラの基本-—-モデルの位置が画面に映るまで" aria-label="Permalink to &quot;座標変換とカメラの基本 — モデルの位置が画面に映るまで&quot;">​</a></h1><p>箱の形を用意したあとも、ゲームの中で床に置く、横へ移す、斜めに回すといった操作が必要です。どこから眺めるかによって画面での見え方も変わります。物体の配置からカメラで映すまで、座標が何を基準にするかを順に追います。<a href="/study/graphics/basics/models-and-meshes.html">モデルとメッシュ</a></p><h2 id="座標は、基準と数値を組み合わせて読む" tabindex="-1">座標は、基準と数値を組み合わせて読む <a class="header-anchor" href="#座標は、基準と数値を組み合わせて読む" aria-label="Permalink to &quot;座標は、基準と数値を組み合わせて読む&quot;">​</a></h2><p><strong>座標</strong>は、基準点である<strong>原点</strong>と、向きを定める軸を使って位置を表す値です。3Dでは通常<code>(x, y, z)</code>の三つを使います。同じ<code>(1, 0, 0)</code>でも、「箱の中心から測るか」「ステージの原点から測るか」で示す場所が変わります。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d9/transforms" target="_blank" rel="noreferrer">Microsoftのモデル空間とワールド空間</a></p><table tabindex="0"><thead><tr><th>座標の段階</th><th>基準と用途</th></tr></thead><tbody><tr><td><strong>ローカル・モデル座標</strong></td><td>そのメッシュや物体の基準から、形や配置を表す。</td></tr><tr><td><strong>ワールド座標</strong></td><td>シーン全体で共有する基準に、物体やカメラを配置する。</td></tr><tr><td><strong>ビュー・カメラ座標</strong></td><td>カメラを基準に、どの方向・距離にあるかを表す。</td></tr><tr><td><strong>投影後の座標</strong></td><td>カメラの投影設定を使い、画面に対応する位置を計算する途中の値。</td></tr><tr><td><strong>スクリーン座標</strong></td><td>描画先の幅と高さに対応する位置。ピクセル単位などで扱う。</td></tr></tbody></table><p><strong>座標変換</strong>は、ある基準で表した値を、別の基準での値へ移す計算です。一般的な描画では、投影後に表示範囲で切り取り、透視除算などを経て、描画先へ配置します。各段階の詳しい数式は<a href="/study/math/rendering/transform.html">行列と変換</a>で扱います。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d9/transforms" target="_blank" rel="noreferrer">Microsoftの変換の流れ</a></p><h2 id="移動、回転、拡大縮小" tabindex="-1">移動、回転、拡大縮小 <a class="header-anchor" href="#移動、回転、拡大縮小" aria-label="Permalink to &quot;移動、回転、拡大縮小&quot;">​</a></h2><p><strong>移動</strong>は位置をずらし、<strong>回転</strong>は基準となる向きを変え、<strong>拡大縮小</strong>は軸ごとの大きさを変えます。これらをまとめて<strong>トランスフォーム</strong>と呼びます。UnityのTransformも、位置、回転、拡縮と親子関係を持ちます。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/class-Transform.html" target="_blank" rel="noreferrer">UnityのTransform</a></p><p>例えば、メッシュ内の頂点が<code>(1, 0, 0)</code>で、物体をX方向に<code>3</code>だけ移動し、回転も拡縮もしなければ、その頂点のワールド位置は<code>(4, 0, 0)</code>です。メッシュ内の形とシーン内の配置を別々に持つと、同じ形を何か所にも置けます。</p><p>親子関係のある物体では、子の配置は親を基準にして表せます。親を動かすと子のワールド上の位置も変わります。複数の変換は順序で結果が変わるため、どの基準で、どの順に操作するかを確認します。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/class-Transform.html" target="_blank" rel="noreferrer">Unityの親子関係</a> · <a href="/study/game/basics/scenes-and-components.html">シーンとコンポーネント</a></p><figure class="study-figure"><img src="'+o+'" alt="モデル内の位置をワールドへ配置し、カメラ基準に変換して、投影と画面への配置を行う。画面で見える大きさの概念比較では、透視投影は同じ大きさでも遠い箱が小さく、正投影は距離で大きさが変わらない。" width="760" height="500" loading="lazy"><figcaption>上は位置を扱う基準、下は同じ大きさの物体の投影の比較です。<a href="/study/images/graphics/transforms-and-cameras.svg" target="_blank" rel="noopener noreferrer">座標と投影の図を拡大</a></figcaption></figure><h2 id="カメラは、どこから何を見るかを決める" tabindex="-1">カメラは、どこから何を見るかを決める <a class="header-anchor" href="#カメラは、どこから何を見るかを決める" aria-label="Permalink to &quot;カメラは、どこから何を見るかを決める&quot;">​</a></h2><p><strong>カメラ</strong>は、位置と向き、見える範囲、投影方法などを持ち、描画する視点を決めます。ビュー変換では、世界の位置をカメラ基準に表し直します。カメラを右へ動かせば、動いていない物体でも画面上の位置は変わります。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#cameras" target="_blank" rel="noreferrer">Khronosのカメラとビュー行列</a></p><p><strong>透視投影</strong>は、遠い物体ほど小さく映す方式です。見える角度を表す**視野角（FOV）**を変えると、一度に映る範囲が変わります。カメラの位置を変える操作と、視野角を変える操作は、別の設定です。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/class-Camera.html" target="_blank" rel="noreferrer">UnityのCameraと投影の設定</a></p><p><strong>正投影</strong>では、カメラからの距離による大きさの変化を付けずに投影します。同じ向き・同じ大きさの物体は、距離だけが違っても同じ大きさに映ります。2Dゲームや設計図のような表示にも使えます。物体の重なりや描画範囲の判定は、この場合も扱います。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#cameras" target="_blank" rel="noreferrer">Khronosの正投影</a> · <a href="https://docs.unity3d.com/6000.0/Documentation/Manual/class-Camera.html" target="_blank" rel="noreferrer">Unityの正投影設定</a></p><h2 id="カメラに向いていても映らない場合" tabindex="-1">カメラに向いていても映らない場合 <a class="header-anchor" href="#カメラに向いていても映らない場合" aria-label="Permalink to &quot;カメラに向いていても映らない場合&quot;">​</a></h2><p>カメラには、どこからどこまでを描くかという範囲があります。<strong>近クリップ面</strong>と<strong>遠クリップ面</strong>は、カメラからの奥行きの範囲を定める境界です。左右上下の範囲も合わせた外側にある部分は切り取られます。物体が消えるときは、位置と大きさに加え、カメラの向きや表示範囲も確認します。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/class-Camera.html" target="_blank" rel="noreferrer">Unityのクリップ面</a> · <a href="/study/math/rendering/camera.html">カメラと射影の詳解</a></p><h2 id="ツールごとの座標の約束を確認する" tabindex="-1">ツールごとの座標の約束を確認する <a class="header-anchor" href="#ツールごとの座標の約束を確認する" aria-label="Permalink to &quot;ツールごとの座標の約束を確認する&quot;">​</a></h2><p>上向きの軸、正面の方向、長さの単位、画面の原点、奥行きの範囲などは、ファイル形式やエンジン、APIの約束に従います。例えばglTFは右手系、上方向を<code>+Y</code>、距離の単位をメートルと定めています。読み込む側は、自分の座標の約束へ合わせて変換します。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#coordinate-system-and-units" target="_blank" rel="noreferrer">Khronosの座標と単位</a></p><p>頂点の位置が画面の色へ変わる続きは、<a href="/study/graphics/basics/light-and-rendered-images.html">光とレンダリングの基本</a>と<a href="/study/graphics/pipeline/overview.html">レンダリングパイプライン</a>へ進みます。</p>',20)])])}const p=t(n,[["render",i]]);export{f as __pageData,p as default};
